(Application-Start: Greeting) {
    Log "Hello, ARO." to the <console>.
    Return an <OK: status> for the <startup>.
}

(Application-Start: Arithmetic) {
    Compute the <total> from 7 * 6.
    Log <total> to the <console>.
    Return an <OK: status> for the <startup>.
}

(Application-Start: Shout) {
    Create the <word> with "aro".
    Compute the <loud: uppercase> from <word>.
    Log <loud> to the <console>.
    Return an <OK: status> for the <startup>.
}

(Application-Start: Totals) {
    Create the <amounts> with [10, 20, 30, 40].
    Compute the <total: sum> from <amounts>.
    Log <total> to the <console>.
    Return an <OK: status> for the <startup>.
}

(Application-Start: Averages) {
    Create the <scores> with [10, 20, 30].
    Compute the <mean: avg> from <scores>.
    Log <mean> to the <console>.
    Return an <OK: status> for the <startup>.
}

(Application-Start: Roll Call) {
    Create the <names> with ["Alice", "Bob", "Carol"].
    for each <name> in <names> {
        Log <name> to the <console>.
    }
    Return an <OK: status> for the <startup>.
}

(Application-Start: Grading) {
    Create the <score> with 80.
    Log "pass" to the <console> when <score> >= 50.
    Return an <OK: status> for the <startup>.
}

(Double: Action takes <number>) {
    Extract the <n> from the <input: number>.
    Compute the <doubled> from <n> * 2.
    Return an <OK: status> with { doubled: <doubled> }.
}

(Application-Start: Doubler) {
    Application.Double the <r> from 21.
    Extract the <value> from the <r: doubled>.
    Log <value> to the <console>.
    Return an <OK: status> for the <startup>.
}

(Application-Start: Joining) {
    Create the <items> with ["a", "b", "c"].
    Compute the <line: join> from <items> with { separator: ", " }.
    Log <line> to the <console>.
    Return an <OK: status> for the <startup>.
}

(Application-Start: Adults) {
    Create the <people> with [{ name: "Alice", age: 30 }, { name: "Bob", age: 12 }, { name: "Carol", age: 18 }].
    Filter the <adults> from the <people> where <age> >= 18.
    for each <person> in <adults> {
        Log <person: name> to the <console>.
    }
    Return an <OK: status> for the <startup>.
}

